css:
.d1120-run,.d1120-wind,.d1120-sway,.d1120-fall,.d1120-fall2{transform-box:fill-box}
.d1120-run{transform-origin:center;animation:d1120-go 3.4s ease-in-out infinite}
.d1120-wind{animation:d1120-go 3.4s ease-in-out infinite}
.d1120-sway{animation:d1120-sw 3s ease-in-out infinite}
.d1120-fall{animation:d1120-fl 3.4s ease-in infinite}
.d1120-fall2{animation:d1120-fl 3.4s ease-in infinite;animation-delay:.5s}
@keyframes d1120-go{0%,15%{transform:translateX(0)}70%,100%{transform:translateX(200px)}}
@keyframes d1120-sw{0%,100%{transform:translateX(0)}50%{transform:translateX(12px)}}
@keyframes d1120-fl{0%,20%{transform:translate(0,0);opacity:1}80%{transform:translate(120px,70px);opacity:1}100%{transform:translate(120px,70px);opacity:0}}
@media (prefers-reduced-motion:reduce){.d1120-run{transform:translateX(200px)}}
